"""
title: MCP Tool Router
description: One connection instead of many — search the tools of all running MCP instances, fetch a schema, call it. Keeps the tool list in the prompt small. Read-only.
author: Torsten Feustel
version: 0.0.12
license: MIT
category: System
"""

import asyncio
import difflib
import inspect
import json
import logging
import re
import time
import unicodedata
from contextlib import asynccontextmanager
from typing import Any

import httpx
from pydantic import BaseModel, Field

# One line per call. Without it, the only way to tell whether a model follows
# find → describe → call is to reconstruct it from the runner's network
# traffic — which is exactly as tedious as it sounds.
logger = logging.getLogger("mcp_tool_router")

# Hard-coded so a copy installed under a different ID still cannot route into
# itself: any instance offering exactly these three tools is a router.
SELF_ID = "mcp_tool_router"
SELF_FINGERPRINT = {"find_tools", "describe_tools", "call_tool"}
UMLAUTS = {"ä": "ae", "ö": "oe", "ü": "ue", "ß": "ss"}
# How app/mcp_runner.py words a failed call: "Error: …", possibly after the
# one-line storage warning it puts in front of every result.
SPAWNER_ERROR = re.compile(r"^(?:Note: [^\n]*\n\n)?Error: ")

# The shipped external_mcp_bridge. Behind these three sits a whole external MCP
# server whose tools the catalog would otherwise never name — a model searching
# for "person" found nothing, and calling one meant nesting arguments twice.
BRIDGE_FINGERPRINT = {"list_tools", "describe_tool", "call_tool"}
# What the bridge's list_tools() and describe_tool() print. Read only after the
# header has matched, so a failure text is never mistaken for a tool list.
BRIDGE_HEADER = re.compile(r"^\d+ tool\(s\) at ")
BRIDGE_LINE = re.compile(r"^([A-Za-z0-9_.\-]+)(?: — (.*))?$")
BRIDGE_PARAM = re.compile(r"^  (\S+) \((.+), (required|optional)\)(?:: (.*))?$")
# How the bridge words a failure — as text, never as is_error.
BRIDGE_FAILURE = ("Call failed:", "Could not reach the external server", "Unknown tool '")


def _norm(word: str) -> str:
    """Lowercase, umlauts spelled out, accents dropped.

    German and English descriptions sit side by side in one installation, so a
    raw substring match misses half the catalog.
    """
    out = word.lower()
    for source, target in UMLAUTS.items():
        out = out.replace(source, target)
    out = unicodedata.normalize("NFKD", out)
    return "".join(c for c in out if not unicodedata.combining(c))


def _words(text: str) -> list[str]:
    """Normalised words of a name or description — `list_mails` is list, mails."""
    return [w for w in re.split(r"[^a-z0-9]+", _norm(text or "")) if w]


def _as_json(value: Any) -> str:
    # Double quotes, umlauts as they are: what a model copies must parse.
    return json.dumps(value, ensure_ascii=False, default=str)


def _advertise(method, required: tuple = ()):
    """Show *method* to the schema with its catch-all removed and *required*
    without their defaults.

    call_tool and describe_tools take more than they advertise: the names
    OpenWebUI's own tool search uses (tool_name/params, handles) and arguments
    a model put next to `tool` instead of into `arguments`. Taking them needs
    defaults and a **kwargs; showing them would make the one required handle
    optional and put the aliases into every prompt. The schema reads
    `__signature__`, Python still calls the real function.
    """
    sig = inspect.signature(method)
    params = [
        p.replace(default=inspect.Parameter.empty) if p.name in required else p
        for p in sig.parameters.values()
        if p.kind is not inspect.Parameter.VAR_KEYWORD
    ]
    method.__signature__ = sig.replace(parameters=params)
    return method


def _as_object(value: Any) -> Any:
    """`arguments`/`params` as a model sent it: an object, or that object
    written out as a JSON string — OpenWebUI's own call_tool asks for the
    string, so a model that has seen both mixes them up."""
    if isinstance(value, str) and value.strip().startswith("{"):
        try:
            return json.loads(value)
        except ValueError:
            return value
    return value


def _first_line(text: str, limit: int = 140) -> str:
    """First sentence-ish of a docstring, collapsed to one line."""
    line = (text or "").strip().split("\n")[0].strip()
    return line[: limit - 1] + "…" if len(line) > limit else line


@asynccontextmanager
async def _mcp_streams(url: str, headers: dict, timeout: int):
    """Read/write streams to an MCP endpoint — across both SDK generations.

    mcp 2.x renamed the transport, moved headers and timeout onto an HTTP
    client that is handed to it, and yields two streams where 1.x yielded
    three. This same tool JSON also runs inside OpenWebUI, whose SDK version is
    not ours to pin, so both shapes stay supported.
    """
    from mcp.client import streamable_http as transport

    opener = getattr(transport, "streamable_http_client", None)
    if opener is not None and "http_client" in inspect.signature(opener).parameters:
        # mcp >= 1.29: headers no longer go to the transport but to an HTTP
        # client handed to it — and 2.x swapped the library that client comes
        # from (httpx2). Take it from the transport module rather than guess.
        http_lib = getattr(transport, "httpx2", None) or getattr(transport, "httpx", None)
        if http_lib is None:  # pragma: no cover - neither name present
            import httpx as http_lib
        async with http_lib.AsyncClient(headers=headers, timeout=timeout) as client:
            async with opener(url, http_client=client) as (read, write, *_):
                yield read, write
        return

    # Older 1.x: headers and timeout go straight to the transport, and it
    # yields a third element nobody here needs.
    async with transport.streamablehttp_client(
        url, headers=headers, timeout=timeout
    ) as (read, write, *_):
        yield read, write


class Tools:
    class Valves(BaseModel):
        manager_url: str = Field(
            default="http://127.0.0.1:7860",
            description="Base URL of the MCP spawner (manager API)",
        )
        auth_token: str = Field(
            default="",
            description="Bearer token for the manager API — use the read-only token from Settings, not the password",
        )
        mcp_token: str = Field(
            default="",
            description="Bearer token of the MCP endpoints (leave empty if none)",
        )
        mcp_base_url: str = Field(
            default="",
            description=(
                "Optional override. Empty = use each instance's URL from the "
                "catalog (works with and without a shared port). Set = "
                "<base>/mcp/<id>, for a router running on another machine."
            ),
        )
        deny_instances: str = Field(
            default="mcp_manager_control",
            description="Comma-separated instance IDs the router must ignore entirely",
        )
        forward_user_identity: bool = Field(
            default=True,
            description=(
                "Pass the verified OpenWebUI user on to the target instance. "
                "Needs identity_mode=optional on this router; the target decides "
                "what it does with the identity."
            ),
        )
        allow_categories: str = Field(
            default="",
            description="Comma-separated categories to expose (empty = all)",
        )
        max_results: int = Field(
            default=60, description="Maximum number of function lines per answer"
        )
        cache_ttl: int = Field(
            default=60, description="Seconds the catalog is reused before refetching"
        )
        request_timeout: int = Field(
            default=60, description="Seconds to wait for a proxied tool call"
        )
        expand_bridges: bool = Field(
            default=True,
            description=(
                "List the tools behind an external MCP bridge as functions of "
                "their own (bridge.search_items) instead of its list/describe/call"
            ),
        )
        bridge_cache_ttl: int = Field(
            default=600,
            description="Seconds a bridge's tool list is reused — it is an external server",
        )

    def __init__(self):
        self.valves = self.Valves()
        self._cache: list[dict] | None = None
        self._cache_time = 0.0
        # instance id → {"time", "tools": {name: spec} | None}
        self._bridges: dict[str, dict] = {}

    # ── catalog ───────────────────────────────────────────────────────────

    def _denied(self) -> set[str]:
        names = {SELF_ID}
        names |= {p.strip() for p in self.valves.deny_instances.split(",") if p.strip()}
        return names

    async def _fetch_catalog(self) -> list[dict]:
        headers = {}
        if self.valves.auth_token:
            headers["Authorization"] = f"Bearer {self.valves.auth_token}"
        url = self.valves.manager_url.rstrip("/") + "/api/instances?include=specs"
        async with httpx.AsyncClient(timeout=15) as client:
            response = await client.get(url, headers=headers)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, list):
            raise RuntimeError("Unexpected manager response")
        if data and "specs" not in data[0]:
            # Guest payload: the allowlist dropped everything but the basics.
            raise RuntimeError(
                "Manager answered without specs — the auth_token valve is missing "
                "or wrong (an unauthenticated caller only gets the guest view)."
            )

        denied = self._denied()
        allowed = {c.strip().lower() for c in self.valves.allow_categories.split(",") if c.strip()}
        catalog = []
        for inst in data:
            if inst.get("status") != "running":
                continue  # the dashboard curates the catalog: stopped = invisible
            if inst.get("id") in denied:
                continue
            specs = inst.get("specs") or []
            if SELF_FINGERPRINT.issubset({s.get("name") for s in specs}):
                continue  # another router — calling it would be a loop
            if allowed and (inst.get("category") or "").lower() not in allowed:
                continue
            if not specs:
                continue
            catalog.append(inst)
        return catalog

    async def _catalog(self, force: bool = False) -> list[dict]:
        fresh = time.time() - self._cache_time < self.valves.cache_ttl
        if self._cache is None or not fresh or force:
            self._cache = await self._fetch_catalog()
            self._cache_time = time.time()
        if self.valves.expand_bridges:
            bridges = [i for i in self._cache if self._is_bridge(i)]
            if bridges:
                await asyncio.gather(*(self._bridge_tools(i, force) for i in bridges))
        return self._cache

    @staticmethod
    def _raw_handles(catalog: list[dict]) -> dict[str, tuple[dict, dict]]:
        """`instance.tool` → (instance, spec) for every function the instances
        themselves declare — bridges with their own three functions."""
        return {
            f"{inst['id']}.{spec['name']}": (inst, spec)
            for inst in catalog
            for spec in inst.get("specs") or []
            if spec.get("name")
        }

    def _handles(self, catalog: list[dict]) -> dict[str, tuple[dict, dict]]:
        """`instance.tool` → (instance, spec) as the model sees them: a bridge
        whose tool list could be read shows the external tools instead of its
        own list/describe/call."""
        out = {}
        for inst in catalog:
            remote = None
            if self.valves.expand_bridges and self._is_bridge(inst):
                remote = (self._bridges.get(inst["id"]) or {}).get("tools")
            if remote:
                for name, spec in remote.items():
                    out[f"{inst['id']}.{name}"] = (inst, spec)
                continue
            for spec in inst.get("specs") or []:
                if spec.get("name"):
                    out[f"{inst['id']}.{spec['name']}"] = (inst, spec)
        return out

    @staticmethod
    def _resolve(raw: str, handles: dict) -> str | None:
        """The handle a model meant: exact, or a short name that is unique.

        `list_mails` instead of `nextcloud_context_agent.list_mails` is what
        a small model writes after reading find_functions() — refusing it
        would only cost another round.
        """
        if raw in handles:
            return raw
        if raw and "." not in raw:
            hits = [h for h in handles if h.split(".", 1)[1] == raw]
            if len(hits) == 1:
                return hits[0]
        return None

    # ── bridges ───────────────────────────────────────────────────────────

    @staticmethod
    def _is_bridge(inst: dict) -> bool:
        names = {s.get("name") for s in inst.get("specs") or []}
        return BRIDGE_FINGERPRINT.issubset(names)

    async def _bridge_tools(self, inst: dict, force: bool = False) -> dict | None:
        """The external tools behind a bridge, read from its list_tools().

        Kept for bridge_cache_ttl: every find_tools() would otherwise reach out
        to an external server. A bridge that cannot answer is asked again after
        a minute and meanwhile shows its own three functions — never nothing.
        """
        entry = self._bridges.get(inst["id"])
        if entry and not force and time.time() < entry["until"]:
            return entry["tools"]
        tools = None
        try:
            text, failed = await asyncio.wait_for(self._run(inst, "list_tools", {}), timeout=20)
            if not failed:
                tools = self._parse_bridge_list(text)
        except Exception as e:
            logger.warning(f"bridge {inst['id']}: could not read its tool list ({type(e).__name__}: {e})")
        ttl = self.valves.bridge_cache_ttl if tools else min(60, self.valves.bridge_cache_ttl)
        self._bridges[inst["id"]] = {"until": time.time() + ttl, "tools": tools}
        return tools

    @staticmethod
    def _parse_bridge_list(text: str) -> dict | None:
        lines = (text or "").strip().splitlines()
        if not lines or not BRIDGE_HEADER.match(lines[0]):
            return None
        tools = {}
        for line in lines[1:]:
            if line.startswith("Next:"):
                break
            match = BRIDGE_LINE.match(line.strip())
            if line.strip() and match:
                name = match.group(1)
                # parameters=None: not read yet — describe_tool() is asked when
                # somebody needs them, not 30 times up front.
                tools[name] = {"name": name, "description": match.group(2) or "",
                               "parameters": None, "bridge": name}
        return tools or None

    @staticmethod
    def _parse_bridge_schema(text: str) -> tuple[str, dict] | None:
        """(description, parameters) out of the bridge's describe_tool() text."""
        lines = (text or "").strip().splitlines()
        start = next((i for i, l in enumerate(lines) if l.startswith("Parameters:")), None)
        if start is None or start < 1:
            return None
        description = "\n".join(lines[1:start]).strip()
        properties, required, last = {}, [], None
        for line in lines[start + 1:]:
            if line.startswith("Call:"):
                break
            match = BRIDGE_PARAM.match(line)
            if match:
                name, kind, flag, desc = match.groups()
                last = properties[name] = {"type": kind}
                if desc:
                    last["description"] = desc
                if flag == "required":
                    required.append(name)
            elif last is not None and line.strip():
                last["description"] = (last.get("description", "") + " " + line.strip()).strip()
        return description, {"type": "object", "properties": properties, "required": required}

    async def _complete(self, inst: dict, spec: dict) -> dict:
        """A bridge tool with its schema filled in — read once, then kept."""
        if not spec.get("bridge") or spec.get("parameters") is not None:
            return spec
        try:
            text, failed = await self._run(inst, "describe_tool", {"name": spec["bridge"]})
        except Exception as e:
            logger.warning(f"bridge {inst['id']}: describe_tool({spec['bridge']}) failed: {e}")
            return spec
        parsed = None if failed else self._parse_bridge_schema(text)
        if parsed:
            description, parameters = parsed
            spec["description"] = description or spec.get("description", "")
            spec["parameters"] = parameters
        return spec

    # ── tools ─────────────────────────────────────────────────────────────

    async def find_tools(
        self, query_words: list[str] = None, category: str = "", mode: str = "or"
    ) -> str:
        """Directory ACROSS all instances: which instance does what. START HERE.

        Call it WITHOUT arguments to see the catalog — that is the cheap, safe
        default. Pass query_words only to narrow a large catalog down; a query
        that matches nothing returns everything instead of failing, so you can
        never end up empty-handed.

        Each line is "instance.action — what it does". Use that exact string
        with describe_tools() to get the parameters, then call_tool() to run
        it. To see everything ONE instance offers, use find_functions().

        Args:
            query_words: Search terms, e.g. ["law", "gesetz"]. Full handles
                like "gesetze_im_internet.get_paragraph" and bare instance IDs
                are accepted too and count as direct hits.
            category: Restrict to one category (as shown in the listing)
            mode: "or" = any word matches (default, recommended),
                "and" = every word must match
        """
        try:
            catalog = await self._catalog()
        except Exception as e:
            return f"Could not read the catalog from the manager: {e}"
        if not catalog:
            return (
                "No instances available. Either none are running, or all of them "
                "are excluded by the deny_instances / allow_categories valves."
            )

        handles = self._handles(catalog)
        words = [w for w in (query_words or []) if str(w).strip()]
        notes: list[str] = []

        # Direct hits first: the model tends to pass the full identifier where
        # keywords are expected — that must be a hit, not a miss.
        direct: list[str] = []
        rest: list[str] = []
        for word in words:
            word = str(word).strip()
            if word in handles:
                direct.append(word)
                notes.append(f"'{word}' matched a tool directly")
            elif any(word == inst["id"] for inst in catalog):
                hits = [h for h in handles if h.startswith(word + ".")]
                direct.extend(hits)
                notes.append(f"'{word}' matched an instance ({len(hits)} tools)")
            else:
                parts = [p for p in _norm(word).replace(".", " ").replace("_", " ").split() if p]
                if len(parts) > 1:
                    notes.append(f"'{word}' split into: {', '.join(parts)}")
                rest.extend(parts)

        if category:
            wanted = _norm(category)
            catalog = [i for i in catalog if _norm(i.get("category") or "") == wanted]
            handles = self._handles(catalog)
            notes.append(f"category filter: {category}")

        selected = list(dict.fromkeys(direct))
        if rest:
            scored = []
            for handle, (inst, spec) in handles.items():
                # The note is searched too: it is where the operator wrote what an
                # instance is *for* when the name alone does not say it — several
                # bridges to external MCPs all carry the same name.
                haystack = _norm(" ".join([
                    inst.get("id", ""), inst.get("name", ""), inst.get("description", ""),
                    inst.get("note") or "", inst.get("category", ""),
                    spec.get("name", ""), spec.get("description", ""),
                ]))
                hits = sum(1 for p in rest if p in haystack)
                if hits and (mode.lower() != "and" or hits == len(rest)):
                    scored.append((hits, handle))
            scored.sort(key=lambda x: (-x[0], x[1]))
            selected += [h for _, h in scored if h not in selected]

        matched = len(selected)
        if words and not selected:
            # A search must never be the gate the model gets stuck at.
            notes.append("no match for those words — showing the complete catalog")
        if not selected:
            selected = list(handles)

        limit = max(1, self.valves.max_results)
        shown, cut = selected[:limit], max(0, len(selected) - limit)
        logger.info(
            f"find_tools(query={words or '-'}, mode={mode}) -> {matched or len(selected)} "
            f"of {len(handles)} tools in {len(catalog)} instances"
        )

        header = (
            f"{len(handles)} tool{'' if len(handles) == 1 else 's'} in "
            f"{len(catalog)} instance{'' if len(catalog) == 1 else 's'}"
        )
        if words:
            header += f" · query: {', '.join(str(w) for w in words)} ({mode.upper()})"
            header += f" · {matched} match(es)"
        lines = [header]
        if notes:
            lines += [f"note: {n}" for n in notes]
        lines.append("")

        by_instance: dict[str, list[str]] = {}
        for handle in shown:
            by_instance.setdefault(handle.split(".", 1)[0], []).append(handle)
        for instance_id, group in by_instance.items():
            inst = handles[group[0]][0]
            # Name and description are optional in a config — don't print empty
            # separators or the ID twice.
            title = instance_id
            if inst.get("name") and inst["name"] != instance_id:
                title += f" — {inst['name']}"
            if inst.get("category"):
                title += f" [{inst['category']}]"
            summary = _first_line(inst.get("description"), 110)
            lines.append(f"{title}: {summary}" if summary else title)
            # One line of it, like the description: the listing is read by a
            # small model, and the full note is in describe_tools().
            note = _first_line(inst.get("note"), 110)
            if note:
                lines.append(f"  note: {note}")
            for handle in group:
                lines.append(f"  {handle} — {_first_line(handles[handle][1].get('description'))}")
            lines.append("")
        if cut:
            # "27 more" alone told the model nothing about *where* — and a
            # small model takes the best of what it sees instead of searching.
            hidden: dict[str, int] = {}
            for handle in selected[limit:]:
                instance_id = handle.split(".", 1)[0]
                hidden[instance_id] = hidden.get(instance_id, 0) + 1
            lines.append(f"({cut} more not shown — find_functions lists all of one instance:")
            for instance_id, count in hidden.items():
                lines.append(f'  find_functions(tool="{instance_id}")  — {count} more there')
            lines.append(")")
        lines.append("Next: describe_tools([\"instance.action\"]) for the parameters,")
        lines.append('then call_tool(tool="instance.action", arguments={...}) to run it.')
        return "\n".join(lines)

    async def find_functions(
        self, tool: str, query_words: list[str] = None, mode: str = "and"
    ) -> str:
        """Everything ONE instance offers — look inside a tool.

        Without query_words: every function name of that instance, nothing cut
        off. With query_words: only the matching functions, with what they do.
        Three matches or fewer come with their parameters and an example call,
        so you can call_tool() right away.

        Args:
            tool: Instance from find_tools(), e.g. "nextcloud_context_agent"
            query_words: Words to narrow down, e.g. ["get", "mail"]
            mode: "and" = every word must match (default), "or" = any word
        """
        try:
            catalog = await self._catalog()
        except Exception as e:
            return f"Could not read the catalog from the manager: {e}"
        inst = self._resolve_instance(str(tool or ""), catalog)
        if inst is None:
            ids = ", ".join(i["id"] for i in catalog) or "(none)"
            logger.info(f"find_functions({tool!r}) -> unknown instance")
            return f"Unknown tool '{tool}'. Instances: {ids}\nCall find_tools() to see what each one does."

        prefix = inst["id"] + "."
        own = {h: spec for h, (_, spec) in self._handles(catalog).items() if h.startswith(prefix)}
        words = [w for p in (query_words or []) for w in _words(str(p))]
        notes = []

        matches: list[str] = []
        if words:
            def hits(handle):
                spec = own[handle]
                vocabulary = _words(spec.get("name", "")) + _words(spec.get("description", ""))
                # Word starts, not substrings: "get" must not find "target".
                return sum(1 for w in words if any(v.startswith(w) for v in vocabulary))

            scored = sorted(((hits(h), h) for h in own), key=lambda x: (-x[0], x[1]))
            if mode.lower() != "or":
                matches = [h for n, h in scored if n == len(words)]
                if not matches:
                    notes.append("no function matches all words — showing those matching any")
            if not matches:
                matches = [h for n, h in scored if n]
            if not matches:
                notes.append("no match for those words — showing every function")

        logger.info(
            f"find_functions({inst['id']}, query={words or '-'}, mode={mode}) -> "
            f"{len(matches) if words else len(own)} of {len(own)}"
        )

        title = inst["id"]
        if inst.get("name") and inst["name"] != inst["id"]:
            title += f" — {inst['name']}"
        lines = [f"{title}: {len(own)} function{'' if len(own) == 1 else 's'}"]
        note = _first_line(inst.get("note"), 110)
        if note:
            lines.append(f"note: {note}")
        if words:
            lines.append(f"query: {', '.join(words)} ({mode.upper()}) · {len(matches)} match(es)")
        lines += [f"note: {n}" for n in notes]
        lines.append("")

        if not matches:
            # Names only: 87 lines with descriptions are too much for a small
            # model, and the names say most of it.
            lines.append(f"Handles are {prefix}<name> — the name alone works too.")
            lines += [h[len(prefix):] for h in sorted(own)]
            lines.append("")
            lines.append(f'Next: find_functions(tool="{inst["id"]}", query_words=["…"]) for descriptions,')
            lines.append('or describe_tools(["<name>"]) for the parameters.')
            return "\n".join(lines)

        shown = matches[: max(1, self.valves.max_results)]
        if len(shown) <= 3:
            blocks = []
            for handle in shown:
                spec = await self._complete(inst, own[handle])
                blocks.append(self._describe(handle, spec, None))
            return "\n".join(lines) + "\n" + "\n\n".join(blocks)
        lines += [f"{h} — {_first_line(own[h].get('description'))}" for h in shown]
        if len(matches) > len(shown):
            lines.append(f"({len(matches) - len(shown)} more — add a word to narrow down)")
        lines.append("")
        lines.append('Next: describe_tools(["instance.action"]) for the parameters.')
        return "\n".join(lines)

    @staticmethod
    def _resolve_instance(raw: str, catalog: list[dict]) -> dict | None:
        """The instance a model meant: its id, a handle of it, its name, or a
        word that only its id/name/note contains ("wikidata")."""
        raw = raw.strip()
        by_id = {i["id"]: i for i in catalog}
        if raw in by_id:
            return by_id[raw]
        if "." in raw and raw.split(".", 1)[0] in by_id:
            return by_id[raw.split(".", 1)[0]]
        wanted = _norm(raw)
        if not wanted:
            return None
        for inst in catalog:
            if wanted in (_norm(inst["id"]), _norm(inst.get("name") or "")):
                return inst
        hits = [i for i in catalog
                if wanted in _norm(" ".join([i["id"], i.get("name") or "", i.get("note") or ""]))]
        return hits[0] if len(hits) == 1 else None

    async def describe_tools(self, tools: list[str] = None, **extra) -> str:
        """Full parameter schema for one or more tools from find_tools().

        Pass the "instance.action" strings from the directory; several at once
        are fine. Do this before call_tool() — the directory intentionally
        omits schemas to keep it small.

        Args:
            tools: Handles, e.g. ["gesetze_im_internet.get_paragraph"]
        """
        if tools is None:
            tools = extra.pop("handles", None)
        if isinstance(tools, str) and tools.strip().startswith("["):
            try:
                tools = json.loads(tools)  # the list written out as JSON
            except ValueError:
                pass
        if isinstance(tools, str):
            tools = [tools]  # one handle, not wrapped in a list
        if not tools:
            logger.info(f"describe_tools: no handles (got {sorted(extra)})")
            return ('Error: describe_tools needs the handles in `tools`, as a list, e.g. '
                    'describe_tools(tools=["external_mcp_bridge.search_items"]). '
                    "find_tools() lists them.")
        try:
            catalog = await self._catalog()
        except Exception as e:
            return f"Could not read the catalog from the manager: {e}"
        handles = self._handles(catalog)

        logger.info(f"describe_tools({list(tools or [])})")
        blocks = []
        for raw in tools or []:
            handle = self._resolve(str(raw).strip(), handles)
            if handle is None:
                blocks.append(self._unknown_handle(str(raw).strip(), handles))
                continue
            inst, spec = handles[handle]
            spec = await self._complete(inst, spec)
            blocks.append(self._describe(handle, spec, inst))
        if not blocks:
            return "No tools given. Call find_tools() to see what exists."
        return "\n\n".join(blocks)

    async def call_tool(self, tool: str = "", arguments: dict = None, **extra) -> str:
        """Run a tool from this router's catalog and return its result.

        This is the only way to run the tools listed by find_tools(). It is not
        the only way to reach those servers in general: if your client already
        has one of them registered as its own MCP server, calling it there is
        fine and cheaper — use this router for everything else.

        `tool` is a STRING VALUE, not a function you can call. "owui_rag.query_knowledge"
        is a handle that belongs in this parameter — calling it by that name directly
        will not work, no matter what your client suggests. The real parameters of the
        target tool go into `arguments` as a nested object:

            call_tool(tool="owui_rag.query_knowledge",
                      arguments={"query": "Meta-Modell", "knowledge": "Psychologie & Therapie"})

        If a call fails, fix the arguments and call this again — do not fall back to
        raw HTTP; there is no direct access to the instances from here.

        Args:
            tool: Handle from find_tools(), e.g. "gesetze_im_internet.get_paragraph"
            arguments: Object with the parameters from describe_tools(),
                e.g. {"law": "bgb", "paragraph": "823"}
        """
        # OpenWebUI's tool search has a call_tool(tool_name, params) of its
        # own; a model that sees both mixes the two shapes. Taken as meant.
        tool = tool or extra.pop("tool_name", "")
        if arguments is None:
            arguments = extra.pop("params", None)
        arguments = _as_object(arguments)
        if arguments is not None and not isinstance(arguments, dict):
            return ('Error: `arguments` must be an object, e.g. '
                    f'call_tool(tool="{tool or "<instance.action>"}", arguments={{"query": "…"}}).')
        # Whatever is left is the target's own parameters, put next to `tool`
        # instead of into `arguments` — Nova did that four times in one chat.
        flat = {k: v for k, v in extra.items() if k not in ("tool_name", "params")}
        if not str(tool or "").strip():
            return await self._missing_handle(arguments or {}, flat)
        if flat:
            logger.info(f"call_tool: moved {sorted(flat)} into arguments")
            arguments = {**flat, **(arguments or {})}

        handle = str(tool or "").strip()
        # The user id, never the token: this line ends up in a log file.
        try:
            from app.identity import get_current_identity
            caller = getattr(get_current_identity(), "sub", None)
        except ImportError:
            caller = None
        logger.info(
            f"call_tool({handle}, args={sorted((arguments or {}).keys())})"
            + (f" for {caller}" if caller else "")
        )
        instance_id = handle.split(".", 1)[0]
        # Checked before the catalog lookup: `tool` is free text, so a model
        # that knows or guesses the name must not slip past the deny list.
        if instance_id in self._denied():
            logger.warning(f"call_tool refused: '{instance_id}' is on the deny list")
            return f"Instance '{instance_id}' is not available through this router."

        try:
            catalog = await self._catalog()
        except Exception as e:
            return f"Could not read the catalog from the manager: {e}"
        handles = self._handles(catalog)
        resolved = self._resolve(handle, handles)
        if resolved is None and handle in self._raw_handles(catalog):
            # A bridge's own list/describe/call: no longer listed once its
            # tools are, but a model or prompt that knows them still works.
            resolved = handle
            handles = {**handles, handle: self._raw_handles(catalog)[handle]}
        if resolved is None:
            logger.info(f"call_tool: unknown handle '{handle}'")
            return self._unknown_handle(handle, handles)
        handle = resolved

        inst, spec = handles[handle]
        try:
            return await self._invoke(inst, spec, handle, arguments or {})
        except Exception as first_error:
            # The instance may have moved to another port since the catalog was
            # cached (the manager reassigns busy ports on start). Refetch once.
            logger.warning(f"call_tool({handle}) failed ({first_error}) — refreshing catalog and retrying")
            try:
                catalog = await self._catalog(force=True)
            except Exception:
                return self._offline(handle, first_error)
            handles = {**self._raw_handles(catalog), **self._handles(catalog)}
            if handle not in handles:
                return (
                    f"'{handle}' is no longer available — the instance was stopped "
                    "or removed. Call find_tools() again."
                )
            inst, spec = handles[handle]
            try:
                return await self._invoke(inst, spec, handle, arguments or {})
            except Exception as second_error:
                return self._offline(handle, second_error)

    describe_tools = _advertise(describe_tools, required=("tools",))
    call_tool = _advertise(call_tool, required=("tool",))

    # ── internals ─────────────────────────────────────────────────────────

    async def _missing_handle(self, arguments: dict, flat: dict) -> str:
        """call_tool without a handle: say where the values belong, and which
        function they most likely were meant for.

        The candidates are the functions that take every one of the given
        names — read from the catalog, never from an earlier call, which
        might have been another user's.
        """
        given = {**flat, **arguments}
        logger.info(f"call_tool: no handle (got {sorted(flat) or '-'}"
                    f"{', arguments ' + str(sorted(arguments)) if arguments else ''})")
        candidates = []
        if given:
            try:
                handles = self._handles(await self._catalog())
            except Exception:
                handles = {}
            for handle, (_, spec) in handles.items():
                props = ((spec.get("parameters") or {}).get("properties") or {})
                if props and set(given) <= set(props):
                    candidates.append(handle)
        lines = ["Error: call_tool needs `tool` — the handle of the function to run."]
        if flat:
            names = ", ".join(sorted(flat))
            lines.append(f"You passed {names} directly. Those are the function's own "
                         "parameters and go into `arguments`.")
        example = _as_json(given) if given else '{"…": "…"}'
        if candidates[:3]:
            lines.append("Call it like this:")
            lines += [f'  call_tool(tool="{h}", arguments={example})' for h in candidates[:3]]
        else:
            lines.append(f'Call it like this: call_tool(tool="<instance.action>", arguments={example})')
            lines.append("find_tools() lists the handles.")
        return "\n".join(lines)

    def _caller_agent_token(self) -> str:
        """The token of the *agent* calling us, when the manager passes it down.

        Empty for a human caller (their identity travels as a user JWT), empty
        outside the framework, and empty unless this instance is configured to
        receive it. Never logged and never returned to a caller.
        """
        try:
            from app import identity as identity_module
            from app.identity import SOURCE_AGENT
        except ImportError:
            return ""
        who = identity_module.get_current_identity()
        if who is None or who.source != SOURCE_AGENT:
            return ""
        return who.raw_token or ""

    def _headers_for(self, inst: dict) -> dict:
        """Exactly two things travel to the target: this router's own bearer,
        and the caller's user token unchanged.

        The bearer says "this client may talk to that MCP server". The user
        token says who is asking — passed through as it arrived, so the target
        verifies it against the shared secret itself. This router vouches for
        nobody and decides nothing: the instance behind it is where access is
        granted or refused, and it must be able to do that without trusting
        anything the router adds.

        Deliberately not forwarded: cookies and every other header of the
        original request. The incoming Authorization is replaced by this
        router's own — with one exception, added on 03.09.: when the caller is
        a named *agent* and the manager hands its token down, that token is
        forwarded instead. Otherwise every agent would arrive at the target as
        the shared bearer, and an instance that decides by agent identity could
        not tell Claude Code from a cron job — which is the distinction agent
        identities exist for.
        """
        headers = {}
        if self.valves.mcp_token:
            headers["Authorization"] = f"Bearer {self.valves.mcp_token}"
        if not self.valves.forward_user_identity:
            return headers
        agent_bearer = self._caller_agent_token()
        if agent_bearer:
            # A named agent called us. Its own token goes on instead of ours,
            # so the target sees who is asking and applies its rules to that
            # agent rather than to "somebody holding the shared token". This
            # only ever happens when the manager hands the token down, which it
            # does for this instance alone (forward_agent_token in its config).
            headers["Authorization"] = f"Bearer {agent_bearer}"
            # And nothing else: an agent travels as a bearer, never as a user
            # token. Falling through to the block below would put it into the
            # user-JWT header, where the target tries to parse it as a JWT and
            # refuses with "malformed token" — found live on 03.09.
            return headers
        try:
            from app import identity as identity_module
        except ImportError:
            # The same tool JSON also runs inside OpenWebUI itself, where there
            # is no framework to ask. Without an identity there is nothing to
            # forward, which is not an error here — the target refuses if it
            # needs one.
            return headers
        who = identity_module.get_current_identity()
        if who is None:
            return headers
        if who.raw_token:
            headers[identity_module.header_name()] = who.raw_token
            return headers
        # Identity established from OpenWebUI's plain headers: there is no
        # token to hand on, so the same four headers are rebuilt. They are a
        # claim either way — this router adds no weight to them, it only keeps
        # the target from seeing an anonymous call where a user made it.
        plain = getattr(identity_module, "PLAIN_HEADERS", {})
        for claim, header in plain.items():
            value = getattr(who, claim, "")
            if value:
                headers[header] = str(value)
        return headers

    async def _invoke(self, inst: dict, spec: dict, handle: str, arguments: dict) -> str:
        if spec.get("bridge"):
            # A model that learned the bridge's own shape nests once more —
            # unambiguous, so unwrapped here rather than answered with an error.
            props = ((spec.get("parameters") or {}).get("properties") or {})
            if (set(arguments) <= {"name", "arguments"} and isinstance(arguments.get("arguments"), dict)
                    and arguments.get("name", spec["bridge"]) == spec["bridge"] and "arguments" not in props):
                arguments = dict(arguments["arguments"])
            text, failed = await self._run(inst, "call_tool", {"name": spec["bridge"], "arguments": arguments})
            own_words = f"{spec['bridge']} reported an error:"
            if failed is False and text.startswith((own_words,) + BRIDGE_FAILURE):
                failed = True
                # The router says it again in front — once is enough.
                text = text[len(own_words):].strip() if text.startswith(own_words) else text
        else:
            text, failed = await self._run(inst, spec["name"], arguments)
        if failed is None:
            return text  # the router's own message, e.g. a reassigned port
        if failed:
            logger.info(f"{handle} returned an error — answering with its schema")
            spec = await self._complete(inst, spec)
            return self._failure(handle, spec, inst, arguments, text)
        return text or "(empty result)"

    async def _run(self, inst: dict, name: str, arguments: dict) -> tuple[str, bool | None]:
        """One call on one instance: (text, failed). failed is None when the
        text is the router's own word and not the instance's answer."""
        from mcp import ClientSession

        base = self.valves.mcp_base_url.strip().rstrip("/")
        url = f"{base}/mcp/{inst['id']}" if base else inst.get("url")
        if not url:
            return f"No reachable address for '{inst['id']}'.", None
        headers = self._headers_for(inst)

        async with _mcp_streams(url, headers, self.valves.request_timeout) as (read, write):
            async with ClientSession(read, write) as session:
                init = await session.initialize()
                # serverInfo in mcp 1.x, server_info in 2.x — reading the wrong
                # one would not fail, it would silently skip the check below.
                info = getattr(init, "server_info", None) or getattr(init, "serverInfo", None)
                served = getattr(info, "name", "")
                if served and served != inst["id"]:
                    # Ports get reassigned and can be recycled: without this the
                    # call could silently land on a different instance.
                    return (
                        f"Address of '{inst['id']}' now serves '{served}' — the port was "
                        "reassigned. Call find_tools() again."
                    ), None
                result = await session.call_tool(name, arguments)

        text = "\n".join(
            getattr(part, "text", "") for part in (result.content or []) if getattr(part, "text", "")
        ).strip()
        failed = getattr(result, "is_error", None)  # 2.x
        if failed is None:
            failed = getattr(result, "isError", False)  # 1.x
        # The spawner's runner answers a failed call as plain text starting
        # with "Error: " — deliberately *not* as is_error, so the model reads
        # it. A wrong parameter name is exactly that case, and exactly the one
        # where the schema lets a model fix its call in one step instead of
        # six. A storage warning may stand in front of it.
        if not failed and SPAWNER_ERROR.match(text):
            failed = True
        return text, bool(failed)

    def _failure(self, handle: str, spec: dict, inst: dict, arguments: dict, text: str) -> str:
        """The error, what to change, a call to copy, and the schema.

        A small model fixes a call by copying, not by reasoning about a
        schema — so the corrected call is built from its own values.
        """
        parts = [f"{handle} reported an error:\n{text or '(no message)'}"]
        hints, fixed = self._argument_hints(spec, arguments)
        if hints:
            parts.append("What to change:\n" + "\n".join(f"  - {h}" for h in hints)
                         + f'\nTry: call_tool(tool="{handle}", arguments={_as_json(fixed)})')
        parts.append(self._describe(handle, spec, inst))
        parts.append(
            f'Not the right function? find_functions(tool="{inst["id"]}", query_words=["…"]) '
            "shows what else this instance offers."
        )
        return "\n\n".join(parts)

    @staticmethod
    def _argument_hints(spec: dict, arguments: dict) -> tuple[list[str], dict]:
        """Which argument names are wrong, which are missing — and the
        arguments as they should have been, with the model's own values.

        Only suggested, never sent: the tool may write data, and a guessed
        rename is not the model's decision to skip.
        """
        schema = spec.get("parameters")
        if not isinstance(schema, dict):
            return [], {}  # schema unknown (a bridge that could not describe itself)
        params = list((schema.get("properties") or {}).keys())
        required = [p for p in schema.get("required") or [] if p in params]
        args = dict(arguments or {})
        hints = []

        if "arguments" not in params and isinstance(args.get("arguments"), dict):
            inner = args.pop("arguments")
            if "name" not in params:
                args.pop("name", None)
            args = {**inner, **args}
            hints.append("the parameters go directly into arguments — not nested a second time")

        fixed = {k: v for k, v in args.items() if k in params}
        unknown = [k for k in args if k not in params]
        leftover = []
        for key in unknown:
            free = [p for p in params if p not in fixed]
            near = difflib.get_close_matches(_norm(key), free, n=1, cutoff=0.6)
            if not near:
                near = [p for p in free if _norm(key) in _norm(p) or _norm(p) in _norm(key)][:1]
            if near:
                fixed[near[0]] = args[key]
                hints.append(f"'{key}' is not a parameter — did you mean '{near[0]}'?")
            else:
                leftover.append(key)

        missing = [p for p in required if p not in fixed]
        if len(leftover) == 1 and len(missing) == 1:
            # One value nobody wants, one required slot nobody filled.
            fixed[missing[0]] = args[leftover[0]]
            hints.append(f"'{leftover[0]}' is not a parameter — probably meant '{missing[0]}' (required)")
            leftover, missing = [], []
        for key in leftover:
            accepted = ", ".join(params) or "none"
            hints.append(f"'{key}' is not a parameter (accepted: {accepted})")
        for name in missing:
            fixed[name] = f"<{name}>"
            hints.append(f"'{name}' is required but missing")

        ordered = {p: fixed[p] for p in params if p in fixed}
        return hints, ordered

    # Enough for "which external MCP, which URL, what to watch out for"; a note
    # longer than this is a document, and it would crowd out the parameters.
    NOTE_LIMIT = 400

    def _describe(self, handle: str, spec: dict, inst: dict | None = None) -> str:
        lines = [f"{handle}", (spec.get("description") or "").strip() or "(no description)"]
        note = " ".join(str((inst or {}).get("note") or "").split())
        if note:
            if len(note) > self.NOTE_LIMIT:
                note = note[: self.NOTE_LIMIT - 1] + "…"
            lines.append(f"Instance note: {note}")
        params = (spec.get("parameters") or {}).get("properties") or {}
        required = set((spec.get("parameters") or {}).get("required") or [])
        if not params:
            lines.append("Parameters: none")
        else:
            lines.append("Parameters:")
            for name, schema in params.items():
                schema = schema if isinstance(schema, dict) else {}
                kind = schema.get("type") or "any"
                if isinstance(schema.get("enum"), list):
                    kind = " | ".join(str(v) for v in schema["enum"])
                flag = "required" if name in required else "optional"
                description = str(schema.get("description") or "").strip()
                default = f", default {schema['default']!r}" if "default" in schema else ""
                lines.append(f"  {name} ({kind}, {flag}{default}){': ' + description if description else ''}")
        if spec.get("bridge") and spec.get("parameters") is None:
            lines[-1:] = ["Parameters: unknown — the external server did not describe them"]
        example = {name: f"<{name}>" for name in params if name in required}
        lines.append(f'Call: call_tool(tool="{handle}", arguments={_as_json(example)})')
        return "\n".join(lines)

    @staticmethod
    def _unknown_handle(handle: str, handles: dict) -> str:
        near = []
        if "." not in handle:
            # A short name that several instances share — say which ones.
            near = [h for h in handles if h.split(".", 1)[1] == handle][:5]
        near = near or difflib.get_close_matches(handle, list(handles), n=5, cutoff=0.4)
        if not near and "." in handle:
            prefix = handle.split(".", 1)[0]
            near = [h for h in handles if h.startswith(prefix + ".")][:5]
        hint = "\n".join(f"  {h}" for h in near)
        return (
            f"Unknown tool '{handle}'."
            + (f" Did you mean:\n{hint}" if near else "")
            + "\nCall find_tools() for the full directory."
        )

    @staticmethod
    def _offline(handle: str, error: Exception) -> str:
        return (
            f"'{handle}' could not be reached — the instance is most likely not "
            f"running anymore. Call find_tools() to see what is available.\n"
            f"(technical detail: {type(error).__name__}: {error})"
        )
